// Generated by tests/make-native.py from src/llama-vocab.cpp of the native
// tree. The body between the NATIVE BODY markers is native text, byte for
// byte. Everything around it answers the few calls the body makes into the
// model loader.
#include "native-dispatch-base.h"

#include <cstdarg>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cctype>
#include <map>
#include <stdexcept>
#include <unordered_map>
#include <utility>

#include "llama-vocab.h"

#define LLAMA_LOG_WARN(...) ((void) 0)
#define LLAMA_LOG_INFO(...) ((void) 0)

static case_cfg_base cfg;

enum { KEY_MERGES = 0, KEY_CHARSMAP = 1 };

static std::string kv(int which) {
    return which == KEY_MERGES ? "tokenizer.ggml.merges"
                               : "tokenizer.ggml.precompiled_charsmap";
}

static std::string format(const char * fmt, ...) {
    char buf[512];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);
    return std::string(buf);
}

// The native block refuses a model by throwing; the class of the refusal is
// what the gate compares, the message text travels beside it.
static int classify(const std::string & e) {
    if (e.rfind("unknown tokenizer: ", 0) == 0)             return 1;
    if (e.rfind("unknown pre-tokenizer type: ", 0) == 0)    return 2;
    if (e.rfind("cannot find tokenizer merges", 0) == 0)    return 3;
    if (e.rfind("invalid gguf type for ", 0) == 0)          return 4;
    if (e.rfind("precompiled_charsmap too small", 0) == 0)  return 5;
    if (e.rfind("Index out of array bounds", 0) == 0)       return 6;
    return 9;
}

// The gguf readers keep the gguf.h signatures but are defined here: libggml is
// not linked into this gate, and the key index is emulated from the case.
int64_t gguf_find_key_base(const struct gguf_context *, const char * key) {
    if (strstr(key, "merges") != nullptr) {
        return cfg.has_merges ? KEY_MERGES : -1;
    }
    if (strstr(key, "precompiled_charsmap") != nullptr) {
        return cfg.has_charsmap ? KEY_CHARSMAP : -1;
    }
    return -1;
}

enum gguf_type gguf_get_kv_type_base(const struct gguf_context *, int64_t id) {
    return id == KEY_CHARSMAP ? cfg.charsmap_kv_type : cfg.merges_kv_type;
}

enum gguf_type gguf_get_arr_type_base(const struct gguf_context *, int64_t id) {
    return id == KEY_CHARSMAP ? cfg.charsmap_arr_type : cfg.merges_arr_type;
}

size_t gguf_get_arr_n_base(const struct gguf_context *, int64_t id) {
    return (size_t) (id == KEY_CHARSMAP ? cfg.charsmap_len : cfg.n_merges);
}

// Eight distinct pairs, so the native rank map counts every merge the case
// asks for and the module's own count can be compared with it.
const char * gguf_get_arr_str_base(const struct gguf_context *, int64_t, size_t i) {
    static const char * words[] = {
        "a b", "ab c", "x y", "xy z", "q r", "qr s", "m n", "mn o",
    };
    return words[i & 7];
}

const void * gguf_get_arr_data_base(const struct gguf_context *, int64_t) {
    static uint32_t blob[64];
    blob[0] = cfg.charsmap_blob;
    return blob;
}

struct loader_stub {
    template <typename T>
    bool get_key(int which, T & out, bool /*required*/ = true) const {
        if (which == 1) { // LLM_KV_VOCAB_SIZE
            if (!cfg.vocab_size_known) {
                return false;
            }
            out = (T) cfg.vocab_size;
            return true;
        }
        return false;
    }
};

#define LLM_KV_TOKENIZER_MERGES KEY_MERGES
#define LLM_KV_TOKENIZER_PRECOMPILED_CHARSMAP KEY_CHARSMAP
#define LLM_KV_VOCAB_SIZE 1

// Generated by tests/make-native.py from the native headers.
const char * vocab_type_name_base(int t) {
    switch (t) {
        case 0: return "NONE";
        case 1: return "SPM";
        case 2: return "BPE";
        case 3: return "WPM";
        case 4: return "UGM";
        case 5: return "RWKV";
        case 6: return "PLAMO2";
        default: return "?";
    }
}

